From 00c82153cdb17f51823471894b340e80059ee6aa Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:43:18 +0100
Subject: [PATCH] applets/notifications: also dismiss on-screen notifications
 on Clear All

Clear All only removed expired notifications, so popups that need to be
closed by hand stayed on screen however many piled up. It now also closes
those, running jobs are kept, and the button shows whenever there are any.

BUG: 518237
---
 applets/notifications/main.qml                    | 15 +++++++++++----
 .../abstractnotificationsmodel.cpp                |  3 ++-
 libnotificationmanager/notifications.h            |  2 +-
 3 files changed, 14 insertions(+), 6 deletions(-)

diff --git a/applets/notifications/main.qml b/applets/notifications/main.qml
index 8d98753eca..49a636a7cf 100644
--- a/applets/notifications/main.qml
+++ b/applets/notifications/main.qml
@@ -222,9 +222,12 @@ PlasmoidItem {
         }
     }

+    readonly property bool hasClearableNotifications: (historyModel.activeNotificationsCount + historyModel.expiredNotificationsCount - historyModel.activeJobsCount) > 0
+        || (Notifications.Globals.popupNotificationsModel.activeNotificationsCount - Notifications.Globals.popupNotificationsModel.activeJobsCount) > 0
+
     function clearNotificationHistoryAndShowOsd() {
-        if (historyModel.expiredNotificationsCount > 0 || historyModel.activeNotificationsCount > 0) {
-            historyModel.clear(NotificationManager.Notifications.ClearExpired);
+        if (root.hasClearableNotifications) {
+            historyModel.clear(NotificationManager.Notifications.ClearExpired | NotificationManager.Notifications.ClearActive);
             Notifications.Globals.shortcuts.showNotificationsHistoryCleaned();
         }
     }
@@ -247,9 +250,13 @@ PlasmoidItem {
             id: clearHistory
             text: i18n("Clear All Notifications")
             icon.name: "edit-clear-history"
-            visible: historyModel.expiredNotificationsCount > 0
+            visible: root.hasClearableNotifications
             onTriggered: {
-                historyModel.clear(NotificationManager.Notifications.ClearExpired);
+                historyModel.clear(NotificationManager.Notifications.ClearExpired | NotificationManager.Notifications.ClearActive);
+                if (historyModel.count === 0) {
+                    root.closePlasmoid();
+                    return;
+                }
                 // clear is async,
                 historyModel.countChanged.connect(closeWhenCleared)
             }
diff --git a/libnotificationmanager/abstractnotificationsmodel.cpp b/libnotificationmanager/abstractnotificationsmodel.cpp
index 2bfd15d12f..863b7d8b3f 100644
--- a/libnotificationmanager/abstractnotificationsmodel.cpp
+++ b/libnotificationmanager/abstractnotificationsmodel.cpp
@@ -553,7 +553,8 @@ void AbstractNotificationsModel::clear(Notifications::ClearFlags flags)
     for (int i = 0; i < d->notifications.count(); ++i) {
         const Notification &notification = d->notifications.at(i);

-        if (flags.testFlag(Notifications::ClearExpired) && (notification.expired() || notification.wasAddedDuringInhibition())) {
+        const bool expired = notification.expired() || notification.wasAddedDuringInhibition();
+        if ((flags.testFlag(Notifications::ClearExpired) && expired) || (flags.testFlag(Notifications::ClearActive) && !expired)) {
             close(notification.id());
         }
     }
diff --git a/libnotificationmanager/notifications.h b/libnotificationmanager/notifications.h
index 25b62c1ea0..17c6913135 100644
--- a/libnotificationmanager/notifications.h
+++ b/libnotificationmanager/notifications.h
@@ -356,7 +356,7 @@ public:
      */
     enum ClearFlag {
         ClearExpired = 1 << 1,
-        // TODO more
+        ClearActive = 1 << 2, ///< Notifications that are still shown, running jobs are never cleared
     };
     Q_ENUM(ClearFlag)
     Q_DECLARE_FLAGS(ClearFlags, ClearFlag)
-- 
